import React, { useEffect, useRef } from 'react';
import './inputitems.css';

const InputItem = ({ 
    label, 
    placeholder = ' ', 
    name, 
    onChange, 
    type = 'text', 
    isTextArea = false, 
    className, 
    value, 
    isPreview = false // ✅ New prop to check if it's in preview mode
}) => {
    const textareaRef = useRef(null);

    // Function to auto-adjust height dynamically
    const adjustHeight = () => {
        if (textareaRef.current) {
            textareaRef.current.style.height = "auto"; 
            textareaRef.current.style.height = `${textareaRef.current.scrollHeight}px`; // Expand dynamically
        }
    };

    useEffect(() => {
        if (!isPreview) { // ✅ Only auto-adjust in the form, not in the preview
            adjustHeight();
        }
    }, [value]);

    return (
        <div className={`row ${className}`}> 
            <div className='input'>
                {!isTextArea ? (
                    <input 
                        onChange={onChange} 
                        placeholder={placeholder} 
                        name={name} 
                        type={type} 
                        value={value} 
                        disabled={isPreview} // ✅ Prevent editing in preview mode
                        style={isPreview ? { border: "none", background: "transparent", outline: "none" } : {}} // ✅ Keep preview clean
                    />
                ) : (
                    <textarea 
                        ref={textareaRef}
                        onChange={(e) => {
                            if (!isPreview) { // ✅ Prevent expanding in preview
                                onChange(e);
                                adjustHeight();
                            }
                        }}
                        placeholder={placeholder} 
                        name={name}
                        value={value} 
                        rows="1" 
                        style={{
                            minHeight: "40px", 
                            resize: isPreview ? "none" : "vertical", // ✅ Allow resizing only in form
                            overflow: "hidden",
                            border: isPreview ? "none" : "1px solid #ccc", // ✅ Remove border in preview
                            background: isPreview ? "transparent" : "#fff", // ✅ Keep preview clean
                            outline: isPreview ? "none" : "auto"
                        }}
                        disabled={isPreview} // ✅ Disable interaction in preview
                    ></textarea>
                )}
                <label>{label}</label>
            </div>
        </div>
    );
};

export default InputItem;
